const allItems = $items;
let aggregatedContent = '';

for (const item of allItems) {
  const url = item.json.url;
  const content = item.json.extractedText || '';

  aggregatedContent += `--- START OF SOURCE: ${url} ---\n\n`;
  aggregatedContent += content;
  aggregatedContent += `\n\n--- END OF SOURCE: ${url} ---\n\n`;
}

// Ana workflow'tan gelen query'yi de dahil et
const originalQuery = $input.first().json.query || '';

return [{ 
  json: { 
    query: originalQuery,
    added_file_context: aggregatedContent 
  } 
}];

const item = $item;
const contentType = item.json.headers['content-type'] || '';
let extractedText = '';

try {
  // Gelen verinin türünü kontrol et
  if (contentType.includes('application/json')) {
    // JSON ise, okunabilir metne çevir
    const jsonData = typeof item.json.data === 'string' ? JSON.parse(item.json.data) : item.json.data;
    extractedText = JSON.stringify(jsonData, null, 2);
  } else if (contentType.includes('text/html')) {
    // HTML ise, etiketleri temizleyerek metni al
    const htmlContent = item.json.data || '';
    // Script ve style etiketlerini tamamen kaldır
    let cleanHtml = htmlContent.replace(/<script[^>]*>.*?<\/script>/gsi, '');
    cleanHtml = cleanHtml.replace(/<style[^>]*>.*?<\/style>/gsi, '');
    // Diğer HTML etiketlerini kaldır
    extractedText = cleanHtml.replace(/<[^>]*>/g, ' ')
                              .replace(/\s\s+/g, ' ')
                              .trim();
  } else {
    // Diğer durumlar (text/plain vb.) için veriyi olduğu gibi al
    extractedText = item.json.data || '';
  }
} catch (error) {
  // Hata durumunda ham veriyi kullan
  extractedText = item.json.data || '';
}

// Çok uzun metinleri kısalt (10000 karakter)
if (extractedText.length > 10000) {
  extractedText = extractedText.substring(0, 10000) + '\n\n[Content truncated due to length...]';
}

// Orijinal veriyi koruyarak ayıklanan metni ekle
item.json.extractedText = extractedText;

return item;

// Ana agent'ten gelen veriyi işle
const inputData = $input.first().json;

// Veri yapısını kontrol et ve normalize et
let query = '';
let sources = [];

// Eğer builderPayload varsa (ana agent'ten geliyorsa)
if (inputData.builderPayload) {
  query = inputData.builderPayload.query || '';
  sources = inputData.builderPayload.sources || [];
} else {
  // Doğrudan gelen veri formatı
  query = inputData.query || '';
  sources = inputData.sources || [];
}

// Eğer query'de URL'ler varsa ve sources boşsa, URL'leri ayıkla
if (sources.length === 0 && query) {
  const urlRegex = /https?:\/\/[^\s]+/g;
  const extractedUrls = query.match(urlRegex) || [];
  sources = extractedUrls;
}

// Sadece geçerli URL'leri filtrele
sources = sources.filter(url => {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
});

return [{ 
  json: { 
    query: query,
    sources: sources,
    originalData: inputData
  } 
}];
